#include <stdio.h>
int gcd(int a,int b){while(b){int t=a%b;a=b;b=t;}return a;}
int main(void){int a,b;if(scanf("%d%d",&a,&b)!=2)return 1;printf("%d\n",gcd(a,b));return 0;}

#include <stdio.h>
int is_prime(int n){for(int i=2;i*i<=n;i++)if(n%i==0)return 0;return 1;}
int main(void){int n;if(scanf("%d",&n)!=1)return 1;puts(is_prime(n)?"prime":"composite");return 0;}

#include <stdio.h>
int prime(int n){if(n<2)return 0;for(int i=2;i*i<=n;i++)if(n%i==0)return 0;return 1;}
int main(void){int a,b,count=0;if(scanf("%d%d",&a,&b)!=2)return 1;for(int n=a;n<=b;n++)if(prime(n))count++;printf("%d\n",count);return 0;}

#include <stdio.h>
int power(int base,int exp){int r=1;for(int i=0;i<exp;i++)r*=base;return r;}
int main(void){int a,b;if(scanf("%d%d",&a,&b)!=2)return 1;printf("%d\n",power(a,b));return 0;}

#include <stdio.h>
int absolute(int n){return n<0?-n:n;}
int main(void){int n;if(scanf("%d",&n)!=1)return 1;printf("%d\n",absolute(n));return 0;}

#include <stdio.h>
long long factorial(int n){if(n<=1)return 1;return n*factorial(n-1);}
int main(void){int n;if(scanf("%d",&n)!=1)return 1;printf("%lld\n",factorial(n));return 0;}

#include <stdio.h>
void swap(int *a,int *b){int t=*a;*a=*b;*b=t;}
int main(void){int a,b;if(scanf("%d%d",&a,&b)!=2)return 1;swap(&a,&b);printf("%d %d\n",a,b);return 0;}

